diff --git a/src/domain/money.ts b/src/domain/money.ts
index 011f1e4..a985ff9 100644
--- a/src/domain/money.ts
+++ b/src/domain/money.ts
@@ -3,7 +3,9 @@ export interface Money {
   readonly currency: string;
 }

-export function money(cents: number, currency = 'EUR'): Money {
+import { settings } from '../config';
+
+export function money(cents: number, currency = settings.currency ?? 'EUR'): Money {
   if (!Number.isInteger(cents)) throw new RangeError('cents must be an integer');
   return { cents, currency };
 }

